import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load image texture
  const imageUrl = config.assetUrls?.imageUrl;
  if (!imageUrl) {
    console.warn('No imageUrl provided for card');
    return group;
  }

  const texture = ctx.textureLoader.load(imageUrl);

  // Create card plane (512:320 aspect ratio = 1.6:1)
  const cardGeometry = new THREE.PlaneGeometry(1.6, 1);
  const cardMaterial = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
  });

  const cardMesh = new THREE.Mesh(cardGeometry, cardMaterial);
  group.add(cardMesh);

  // Add text label using MSDF
  if (ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.createTextMesh({
      text: 'Collection 3',
      fontSize: 0.34,
      fontFamily: 'Lora',
      fontWeight: 400,
      color: 0x16161d,
      anchorX: 'center',
      anchorY: 'middle',
    });

    if (textMesh) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Apply scene position transform
  const pos = config.scenePosition || {};
  group.position.set(pos.x || 0, pos.y || 0, pos.z || 0);

  if (pos.rotationXYZ) {
    group.rotation.fromArray(pos.rotationXYZ);
  }
  if (pos.scaleXYZ) {
    group.scale.fromArray(pos.scaleXYZ);
  }

  // Resource cleanup
  group.userData.cleanup = () => {
    cardGeometry.dispose();
    cardMaterial.dispose();
    texture.dispose();
    gsap.killTweensOf(group);
  };

  // Event handlers (empty for static node)
  group.userData.handlers = {};

  return group;
}
